describe("generator", () => {
  it("prints the table", () => {
    const out: string[] = [];
    for (const [ref, customer, start, end] of ROWS) {
      const contract = contractFor(customer, start.slice(0, 10));
      const pence = Math.round(evaluateSpan({ start: start, end: end }, contract).total * 100);
      out.push(ref + "|" + pence);
    }
    console.log("FIXTURE_TOTALS\n" + out.join("\n"));
    expect(ROWS.length).toBe(61);
  });
});
